  def language_to_kv:
    split("|")
    | [range(0; length; 3) as $i
       | .[$i:$i+3]
       | select(length == 3 and .[0] == "LANGUAGE")
       | "\(.[1])=\(.[2])"]
    | join(",");
  walk(
    if type == "object" and has("name") and (.name|type=="string") and (.name|startswith("LANGUAGE|"))
    then .name |= language_to_kv
    else .
    end
  )
  | [.. | objects | select(has("name")) | .name][0:6]
' backend/data/config/library.json","workdir":"/home/alextub/Documents/apiProject1"}

