payload.arguments:
{"cmd":"tmp=$(mktemp) && jq '
  def kv_to_obj:
    split(",")
    | map(capture("^(?<k>[^=,]+)=(?<v>.*)$"))
    | map({key:.k, value:.v})
    | from_entries;
  walk(
    if type=="object" and has("name") and (.name|type=="string") and (.name|test("^[^=,]+=[^,]*(,[^=,]+=[^,]*)*$"))
    then .name |= kv_to_obj
    else .
    end
  )
' backend/data/config/library.json > "$tmp" && mv "$tmp" backend/data/config/library.json","workdir":"/home/alextub/Documents/apiProject1"}

