payload.arguments:
{"cmd":"jq '
  def norm: ascii_downcase | gsub("[^a-z0-9]"; "");
  . as $root
  | ($root.press | map({press_id, norm_en:(.name.EN | norm)})) as $presses
  | ($root.die
      | sort_by(.id)
      | map(
          . as $d
          | (($d.press_die_match_code | norm | sub("^p"; ""))) as $code
          | ($presses | map(select(.norm_en | contains($code))) | sort_by(.press_id) | first // ($presses|first)) as $best
          | {die_id:$d.id, code:$d.press_die_match_code, press_id:$best.press_id, press_norm:$best.norm_en}
        ))
' backend/data/config/library.json","workdir":"/home/alextub/Documents/apiProject1"}

