  is_obsolete?: boolean
  created_at?: string
  obsolete_at?: string | null
}

export interface PressModeRecord {
  id: number
  press_id?: number | null
  owner_user_id?: number | null
  name?: unknown
  properties: Record<string, unknown>
  is_default_press_mode: boolean
  is_obsolete?: boolean
  created_at?: string
  obsolete_at?: string | null
}

export interface PressDieMapRecord {
  press_id: number
  die_id: number
  owner_user_id?: number | null
  is_matching_as_top: boolean
  is_matching_as_bottom: boolean
  is_matching_as_left: boolean
  is_matching_as_right: boolean
  is_obsolete: boolean
  created_at?: string
  obsolete_at?: string | null
}

export interface DieTypeRecord {
  id: number
  name: unknown
}

// Lineage + diff
export interface LineageNode {
  document_id: number
  source_document_id?: number | null
  name: string
  created_at: string
}

export interface DocumentLineageResponse {
  target_document_id: number
  ancestors: LineageNode[]
  descendants: LineageNode[]
}

export interface BlockDiffEntry {
  index: number
  change_type: 'added' | 'removed' | 'modified'
  left_block_id?: string | null
  right_block_id?: string | null
  left_block_type_id?: string | null
  right_block_type_id?: string | null
  left_props?: Record<string, unknown> | null
  right_props?: Record<string, unknown> | null
}

export interface DocumentDiffResponse {
  left_document_id: number
  right_document_id: number
  left_name: string
  right_name: string
  total_changes: number
  changes: BlockDiffEntry[]
}

// Edit sessions
export interface EditSession {
  session_id: string
  document_id: number
  editor_user_id: number
  started_at: string
  ended_at?: string | null
}

export interface EditSessionListResponse {
  sessions: EditSession[]
  total: number
}

// Search
export interface SearchResult {
  block_id: string
  document_id: number
  snippet: string
  block_type_id: string
}

export interface SearchResponse {
  results: SearchResult[]
  total: number
}

